import copy

def test_requirement_1_nested_merge():
    base = {"db": {"host": "a", "port": 1}}
    override = {"db": {"port": 2}}
    expected = {"db": {"host": "a", "port": 2}}
    assert merge(base, override) == expected

def test_requirement_2_lists_replaced():
    base = {"items": [1, 2]}
    override = {"items": [3]}
    expected = {"items": [3]}
    assert merge(base, override) == expected

def test_requirement_3_none_removes_key():
    base = {"a": 1, "b": {"c": 2, "d": 3}}
    override = {"b": {"c": None}}
    expected = {"a": 1, "b": {"d": 3}}
    assert merge(base, override) == expected

def test_requirement_4_type_mismatch_override_wins():
    base = {"a": {"b": 1}}
    override = {"a": 2}
    expected = {"a": 2}
    assert merge(base, override) == expected

    base = {"a": 1}
    override = {"a": {"b": 2}}
    expected = {"a": {"b": 2}}
    assert merge(base, override) == expected

def test_requirement_5_no_mutation_and_deep_copy():
    base = {"a": {"b": 1}, "c": [1, 2]}
    override = {"a": {"b": 2}, "c": [3]}

    base_copy = copy.deepcopy(base)
    override_copy = copy.deepcopy(override)

    result = merge(base, override)

    # Check result is correct
    assert result == {"a": {"b": 2}, "c": [3]}

    # Check base and override are not modified
    assert base == base_copy
    assert override == override_copy

    # Check result shares no dicts or lists with inputs
    # Modifying result should not affect base or override
    result["a"]["b"] = 99
    result["c"].append(4)

    assert base["a"]["b"] == 1
    assert base["c"] == [1, 2]
    assert override["a"]["b"] == 2
    assert override["c"] == [3]

def test_load_layers_works():
    layer1 = {"a": 1, "b": {"c": 2}}
    layer2 = {"b": {"d": 3}, "e": 4}
    layer3 = {"b": {"c": None}, "a": 5}

    # layer1: {"a": 1, "b": {"c": 2}}
    # layer2: {"a": 1, "b": {"c": 2, "d": 3}, "e": 4}
    # layer3: {"a": 5, "b": {"d": 3}, "e": 4}

    expected = {"a": 5, "b": {"d": 3}, "e": 4}
    assert load_layers(layer1, layer2, layer3) == expected

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])
